import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.ServerStoreInfo{StoreInfo: protocol.Option(protocol.StoreEntryPointInfo{StoreID: "sid", StoreName: "Store"})}
PRESENT = bytes.fromhex("01037369640553746f7265")

# generated by gophertunnel b8bd735:
# packet.ServerStoreInfo{}
ABSENT = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.ServerStoreInfoPacket(
            client_store_entry_point_configuration=v2225.ClientStoreEntryPointConfiguration(
                store_id="sid", store_name="Store"
            )
        ),
        PRESENT,
        id="present",
    ),
    pytest.param(v2225.ServerStoreInfoPacket(), ABSENT, id="absent"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_store_info_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_store_info_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
